node -e "
const fs = require('fs');
const crypto = require('crypto');
const path = require('path');
const { execSync } = require('child_process');

const serviceDir = path.join(process.cwd(), 'services', 'com.cinejoy.tv.service');
const files = [
  'crush.wasm',
  'hls-proxy.js',
  'http-client.js',
  'index.js',
  'package.json',
  'resolver.js',
  'services.json'
];

const ipkPath = path.join(process.cwd(), 'dist', 'com.cinejoy.tv_1.0.0_all.ipk');
console.log('Comparing against IPK:', ipkPath);

let allMatch = true;
for (const file of files) {
  const filePath = path.join(serviceDir, file);
  const fileBuf = fs.readFileSync(filePath);
  const diskHash = crypto.createHash('sha256').update(fileBuf).digest('hex');

  // Extract from IPK
  const cmd = 'ar -p \"' + ipkPath + '\" data.tar.gz | tar -zxf - usr/palm/services/com.cinejoy.tv.service/' + file + ' -O';
  const ipkBuf = execSync(cmd);
  const ipkHash = crypto.createHash('sha256').update(ipkBuf).digest('hex');

  const match = diskHash === ipkHash;
  if (!match) allMatch = false;
  console.log(file.padEnd(20), 'Disk: ' + diskHash, 'IPK: ' + ipkHash, 'Match:', match, 'Size:', fileBuf.length);
}
console.log('ALL MATCH:', allMatch);
"

