let allMatch = true;
for (const file of files) {
  const filePath = path.join(serviceDir, file);
  const fileBuf = fs.readFileSync(filePath);
  const diskHash = crypto.createHash('sha256').update(fileBuf).digest('hex');

  // Extract from IPK backup
  const cmd = 'ar -p \"' + ipkBakPath + '\" data.tar.gz | tar -zxf - usr/palm/services/com.cinejoy.tv.service/' + file + ' -O';
